// Photos come from Unsplash (generated by jk/tools/unsplash_photos.py from photos.plan.json - never edit
// photos.json by hand). Images are hotlinked from Unsplash's CDN and credited on /credits/, as Unsplash requires.
import photosJson from "./photos.json";

export type Photo = {
  id: string;
  url: string;
  width: number;
  height: number;
  alt: string;
  color: string;
  photographer: string;
  photographerUrl: string;
  photoUrl: string;
};

const photos = photosJson as Record<string, Photo>;

export function photo(slot: string): Photo | undefined {
  return photos[slot];
}

/** Sized, compressed image URL from Unsplash's CDN (it crops and converts to WebP/AVIF automatically). */
export function photoSrc(p: Photo, width: number, height?: number) {
  const size = height ? `&w=${width}&h=${height}&fit=crop&crop=entropy` : `&w=${width}`;
  return `${p.url}${size}&q=75&auto=format`;
}

export const allPhotos = Object.entries(photos);

/** Unsplash home link for the credits page (same utm tag as the photo links, per the Unsplash guidelines). */
export const unsplashUrl = "https://unsplash.com/?utm_source=primecraft_concept_sites&utm_medium=referral";
